67	@CrossOrigin(exposedHeaders = "errors, content-type")
68	@RequestMapping("/api")
69	public class OwnerRestControllerV1 implements OwnersApi {
70	
71	    /**
72	     * A pragmatic syntactic check for an email address: a non-empty local part, an {@code @},
73	     * and a dotted domain. Deliberately conservative so obviously malformed values (e.g. a bare
74	     * word with no {@code @}) are rejected while ordinary addresses are accepted.
75	     */
76	    private static final Pattern EMAIL_PATTERN =
77	        Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
78	
79	    private final ClinicService clinicService;
