112	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
113	    @Override
114	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
115	        Owner owner = this.clinicService.findOwnerById(ownerId);
116	        if (owner == null) {
117	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
118	        }
119	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
120	    }
