122	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
123	    @Override
124	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
125	        List<String> missingFields = new ArrayList<>();
126	        if (isBlank(ownerFieldsDto.getFirstName())) {
127	            missingFields.add("firstName");
128	        }
129	        if (isBlank(ownerFieldsDto.getLastName())) {
130	            missingFields.add("lastName");
131	        }
132	        String normalizedAddress = normalizeAddress(ownerFieldsDto.getAddress());
133	        if (isBlank(normalizedAddress)) {
134	            missingFields.add("address");
135	        }
136	        if (isBlank(ownerFieldsDto.getCity())) {
137	            missingFields.add("city");
138	        }
139	        if (isBlank(ownerFieldsDto.getTelephone())) {
140	            missingFields.add("telephone");
141	        }
142	        if (!missingFields.isEmpty()) {
143	            throw new MissingOwnerFieldsException(missingFields);
144	        }
145	        LocalDate registrationDate = toBusinessDay(
146	            ownerFieldsDto.getRegistrationDate() != null
147	                ? ownerFieldsDto.getRegistrationDate()
148	                : LocalDate.now());
149	        long registeredOnDay = this.clinicService.findAllOwners().stream()
150	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
151	            .count();
152	        if (registeredOnDay >= 100) {
153	            throw new DailyRegistrationLimitException(
154	                "100 or more owners have already been registered today");
155	        }
156	        String city = ownerFieldsDto.getCity();
157	        long ownersInCity = this.clinicService.findAllOwners().stream()
158	            .filter(existing -> city != null && city.equalsIgnoreCase(existing.getCity()))
159	            .count();
160	        if (ownersInCity >= 50) {
161	            throw new CityAtCapacityException(
162	                "the owner's city already contains 50 or more owners");
163	        }
164	        ownerFieldsDto.setAddress(normalizedAddress);
165	        String lastName = normalizeHousehold(ownerFieldsDto.getLastName());
166	        List<Owner> householdMembers = this.clinicService.findAllOwners().stream()
167	            .filter(existing -> lastName.equals(normalizeHousehold(existing.getLastName()))
168	                && normalizedAddress.equals(normalizeAddress(existing.getAddress())))
169	            .toList();
170	        String householdId = null;
171	        if (!householdMembers.isEmpty()) {
172	            if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
173	                throw new DuplicateHouseholdException(
174	                    "an owner with the same last name and address already exists");
175	            }
176	            // Joining an existing household: share a stable identifier with every member,
177	            // backfilling any members created before the household was formed.
178	            householdId = householdId(lastName, normalizedAddress);
179	            for (Owner member : householdMembers) {
180	                if (!householdId.equals(member.getHouseholdId())) {
181	                    member.setHouseholdId(householdId);
182	                    this.clinicService.saveOwner(member);
183	                }
184	            }
185	        }
186	        String telephone = toE164(ownerFieldsDto.getTelephone());
187	        boolean telephoneInUse = this.clinicService.findAllOwners().stream()
188	            .anyMatch(existing -> telephone.equals(existing.getTelephone()));
189	        if (telephoneInUse) {
190	            throw new DuplicateTelephoneException(
191	                "an owner with the same E.164 telephone already exists");
192	        }
193	        ownerFieldsDto.setTelephone(telephone);
194	        ownerFieldsDto.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
195	        HttpHeaders headers = new HttpHeaders();
196	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
197	        owner.setRegistrationDate(registrationDate);
198	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
199	        owner.setHouseholdId(householdId);
200	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
201	        this.clinicService.saveOwner(owner);
202	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
203	        headers.setLocation(UriComponentsBuilder.newInstance()
204	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
205	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
206	    }
