302	    private static boolean isBlank(String value) {
303	        return value == null || value.isBlank();
304	    }
305	
306	    /**
307	     * Rolls a registration date forward to the next business day: when it falls on a Saturday or
308	     * Sunday it is advanced to the following Monday; a weekday is returned unchanged. This is applied
309	     * to the effective registration date (whether supplied in the request or defaulted to the server
310	     * date), so every value derived from the registration date sees the adjusted business day.
311	     */
312	    private static LocalDate toBusinessDay(LocalDate date) {
313	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY) {
314	            date = date.plusDays(1);
315	        }
316	        return date;
317	    }
318	
319	    /**
320	     * Normalizes a last name for household-duplicate comparison: leading and trailing whitespace is
321	     * trimmed, every internal run of whitespace is collapsed to a single space, and the result is
322	     * lower-cased so that last names are compared case-insensitively.
323	     */
324	    private static String normalizeHousehold(String value) {
325	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
326	    }
327	
328	    /** Common street-type abbreviations expanded to their canonical full form during normalization. */
329	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
330	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
331	
332	    /**
333	     * Normalizes an address to its canonical stored form: leading and trailing whitespace is
334	     * trimmed, every internal run of whitespace is collapsed to a single space, the result is
335	     * upper-cased, and common street-type abbreviations are expanded token-by-token
336	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} or
337	     * whitespace-only value normalizes to the empty string. This form is both stored/returned and
338	     * used for every address comparison (household-duplicate detection and the shared household id).
339	     */
340	    private static String normalizeAddress(String value) {
341	        if (value == null) {
342	            return "";
343	        }
344	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
345	        if (collapsed.isEmpty()) {
346	            return "";
347	        }
348	        String[] tokens = collapsed.split(" ");
349	        StringBuilder sb = new StringBuilder();
350	        for (int i = 0; i < tokens.length; i++) {
351	            if (i > 0) {
352	                sb.append(' ');
353	            }
354	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
355	        }
356	        return sb.toString();
357	    }
358	
359	    /**
360	     * Derives the stable {@code householdId} shared by all owners in a household. It is a
361	     * deterministic function of the normalized last name and address, so every owner that
362	     * shares those values maps to the same identifier regardless of creation order.
363	     */
364	    private static String householdId(String normalizedLastName, String normalizedAddress) {
365	        String key = normalizedLastName + "\n" + normalizedAddress;
366	        return UUID.nameUUIDFromBytes(key.getBytes(StandardCharsets.UTF_8)).toString();
367	    }
368	
369	    /**
370	     * Builds the {@code customerCode} assigned to a new owner, formatted
371	     * {@code '<CITY3>-<LAST3>-<NNNN>'}: {@code CITY3} is the upper-cased first three letters of the
372	     * owner's city, {@code LAST3} is the upper-cased first three letters of the owner's last name,
373	     * and {@code NNNN} is a per-city 4-digit zero-padded sequence equal to one more than the number
374	     * of owners already in that city (e.g. {@code 'SYD-SMI-0007'}).
375	     */
376	    private String nextCustomerCode(String city, String lastName) {
377	        String city3 = prefix3(city);
378	        String last3 = prefix3(lastName);
379	        long sequence = this.clinicService.findAllOwners().stream()
380	            .filter(existing -> city != null && city.equalsIgnoreCase(existing.getCity()))
381	            .count() + 1L;
382	        return String.format("%s-%s-%04d", city3, last3, sequence);
383	    }
384	
385	    /** Upper-cased first three letters (any non-letter removed) of the given value. */
386	    private static String prefix3(String value) {
387	        String letters = value == null ? "" : value.replaceAll("[^\\p{L}]", "");
388	        return letters.substring(0, Math.min(3, letters.length())).toUpperCase(Locale.ROOT);
389	    }
390	
391	    /**
392	     * Counts the existing owners that share the given first name and last name, compared
393	     * case-insensitively. This is evaluated over the owners that already exist (i.e. before the
394	     * owner currently being created is saved), so it reflects how many namesakes preceded the
395	     * new owner.
396	     */
397	    private int countNamesakes(String firstName, String lastName) {
398	        return (int) this.clinicService.findAllOwners().stream()
399	            .filter(existing -> firstName != null && firstName.equalsIgnoreCase(existing.getFirstName())
400	                && lastName != null && lastName.equalsIgnoreCase(existing.getLastName()))
401	            .count();
402	    }
403	
404	    /**
405	     * Normalizes a telephone number to E.164 form. Spaces, dashes and brackets are stripped. A
406	     * leading {@code '+'} and its country code are kept as-is; otherwise the number is treated as a
407	     * national one, a single leading {@code '0'} is dropped, and the default country code
408	     * {@code '+61'} is prepended. The result must have 8 to 15 digits after the {@code '+'},
409	     * otherwise an {@link InvalidTelephoneException} is raised (reported to the client as 400).
410	     */
411	    private static String toE164(String telephone) {
412	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s()-]", "");
413	        String digits;
414	        if (cleaned.startsWith("+")) {
415	            digits = cleaned.substring(1);
416	        } else {
417	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
418	            digits = "61" + national;
419	        }
420	        if (!digits.matches("[0-9]{8,15}")) {
421	            throw new InvalidTelephoneException(
422	                "telephone must form a valid E.164 number with 8 to 15 digits");
423	        }
424	        return "+" + digits;
425	    }
426	
427	    /**
428	     * Email is optional: an absent (or blank) value is left as {@code null}. When a value is
429	     * present it must be a syntactically valid address, otherwise an {@link InvalidEmailException}
430	     * is raised (reported to the client as 400). A valid value is returned lower-cased so it is
431	     * stored and returned in canonical form.
432	     */
433	    private static String normalizeEmail(String email) {
434	        if (isBlank(email)) {
435	            return null;
436	        }
437	        String trimmed = email.trim();
438	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
439	            throw new InvalidEmailException("email must be a syntactically valid address");
440	        }
441	        return trimmed.toLowerCase(Locale.ROOT);
442	    }
443	}
